module tb;
    reg clk;
    reg load;
    reg [1:0] ena;
    reg [99:0] data;
    wire [99:0] q;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation
    always #5 clk = ~clk;

    integer errors = 0;
    reg [99:0] expected;

    initial begin
        clk = 0;
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        expected = 100'h0;

        // Give time for reset/initial values
        @(posedge clk);

        // Test 1: Synchronous Load
        @(negedge clk);
        load = 1'b1;
        ena = 2'b00;
        data = 100'h123456789ABCDEF0123456789ABCDEF0;
        expected = data;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Load failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Test 2: Disable / Hold (ena = 2'b00)
        @(negedge clk);
        load = 1'b0;
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Hold (00) failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Test 3: Disable / Hold (ena = 2'b11)
        @(negedge clk);
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Hold (11) failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Test 4: Rotate Right (ena = 2'b01) with a known single-bit pattern
        @(negedge clk);
        load = 1'b1;
        data = 100'h00000000000000000000000000000001; // LSB set
        expected = data;
        @(posedge clk); // Load

        @(negedge clk);
        load = 1'b0;
        ena = 2'b01; // Rotate Right
        expected = {expected[0], expected[99:1]}; // Expected rotation
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Rotate Right failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Test 5: Rotate Left (ena = 2'b10) with a known MSB pattern
        @(negedge clk);
        load = 1'b1;
        data = 100'h80000000000000000000000000000000; // MSB set
        expected = data;
        @(posedge clk); // Load

        @(negedge clk);
        load = 1'b0;
        ena = 2'b10; // Rotate Left
        expected = {expected[98:0], expected[99]}; // Expected rotation
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Rotate Left failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Test 6: Priority check - load overrides ena
        @(negedge clk);
        load = 1'b1;
        ena = 2'b10; // Rotate left requested, but load is also high
        data = 100'hDEADBEEFDEADBEEFDEADBEEFDEADBEEF;
        expected = data;
        @(posedge clk);
        #1;
        if (q !== expected) begin
            $display("ERROR: Load priority over ena failed. Expected %h, Got %h", expected, q);
            errors = errors + 1;
        end

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
